1	package org.jsoup.select;
2	
3	import org.jsoup.helper.Regex;
4	import org.jsoup.internal.StringUtil;
5	import org.jsoup.helper.Validate;
6	import org.jsoup.nodes.CDataNode;
7	import org.jsoup.nodes.Comment;
8	import org.jsoup.nodes.DataNode;
9	import org.jsoup.nodes.LeafNode;
10	import org.jsoup.nodes.Node;
11	import org.jsoup.nodes.TextNode;
12	import org.jsoup.parser.TokenQueue;
13	import org.jspecify.annotations.Nullable;
14	
15	import java.util.function.Function;
16	import java.util.regex.Matcher;
17	import java.util.regex.Pattern;
18	
19	import static org.jsoup.select.StructuralEvaluator.ImmediateParentRun;
20	import static org.jsoup.internal.Normalizer.normalize;
21	
22	/**
23	 * Parses a CSS selector into an Evaluator tree.
24	 */
25	public class QueryParser implements AutoCloseable {
26	    private final static char[] Combinators = {'>', '+', '~'}; // ' ' is also a combinator, but found implicitly
27	    private final static String[] AttributeEvals = new String[]{"=", "!=", "^=", "$=", "*=", "~="};
28	    private final static char[] SequenceEnders = {',', ')'};
29	
30	    private final TokenQueue tq;
31	    private final String query;
32	    private boolean inNodeContext; // ::comment:contains should act on node value, vs element text
33	
34	    /**
35	     * Create a new QueryParser.
36	     * @param query CSS query
37	     */
38	    private QueryParser(String query) {
39	        Validate.notEmpty(query);
40	        query = query.trim();
41	        this.query = query;
42	        this.tq = new TokenQueue(query);
43	    }
44	
45	    /**
46	     Parse a CSS query into an Evaluator. If you are evaluating the same query repeatedly, it may be more efficient to
47	     parse it once and reuse the Evaluator.
48	
49	     @param query CSS query
50	     @return Evaluator
51	     @see Selector selector query syntax
52	     @throws Selector.SelectorParseException if the CSS query is invalid
53	     */
54	    public static Evaluator parse(String query) {
55	        try (QueryParser p = new QueryParser(query)) {
56	            return p.parse();
57	        } catch (IllegalArgumentException e) {
58	            throw new Selector.SelectorParseException(e.getMessage());
59	        }
60	    }
61	
62	    /**
63	     Parse the query. We use this simplified expression of the grammar:
64	     <pre>
65	     SelectorGroup   ::= Selector (',' Selector)*
66	     Selector        ::= [ Combinator ] SimpleSequence ( Combinator SimpleSequence )*
67	     SimpleSequence  ::= [ TypeSelector ] ( ID | Class | Attribute | Pseudo )*
68	     Pseudo           ::= ':' Name [ '(' SelectorGroup ')' ]
69	     Combinator      ::= S+         // descendant (whitespace)
70	     | '>'       // child
71	     | '+'       // adjacent sibling
72	     | '~'       // general sibling
73	     </pre>
74	
75	     See <a href="https://www.w3.org/TR/selectors-4/#grammar">selectors-4</a> for the real thing
76	     */
77	    Evaluator parse() {
78	        Evaluator eval = parseSelectorGroup();
79	        tq.consumeWhitespace();
80	        if (!tq.isEmpty())
81	            throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
82	        return eval;
83	    }
84	
85	    Evaluator parseSelectorGroup() {
86	        // SelectorGroup. Into an Or if > 1 Selector
87	        Evaluator left = parseSelector();
88	        while (tq.matchChomp(',')) {
89	            Evaluator right = parseSelector();
90	            left = or(left, right);
91	        }
92	        return left;
93	    }
94	
95	    Evaluator parseSelector() {
96	        // Selector ::= [ Combinator ] SimpleSequence ( Combinator SimpleSequence )*
97	        tq.consumeWhitespace();
98	
99	        Evaluator left;
100	        if (tq.matchesAny(Combinators)) {
101	            // e.g. query is "> div"; left side is root element
102	            left = new StructuralEvaluator.Root();
103	        } else {
104	            left = parseSimpleSequence();
105	        }
106	
107	        while (true) {
108	            char combinator = 0;
109	            if (tq.consumeWhitespace())
110	                combinator = ' ';            // maybe descendant?
111	            if (tq.matchesAny(Combinators)) // no, explicit
112	                combinator = tq.consume();
113	            else if (tq.matchesAny(SequenceEnders)) // , - space after simple like "foo , bar"; ) - close of :has()
114	                break;
115	
116	            if (combinator != 0) {
117	                Evaluator right = parseSimpleSequence();
118	                left = combinator(left, combinator, right);
119	            } else {
120	                break;
121	            }
122	        }
123	        return left;
124	    }
125	
126	    Evaluator parseSimpleSequence() {
127	        // SimpleSequence ::= TypeSelector? ( Hash | Class | Pseudo )*
128	        Evaluator left = null;
129	        tq.consumeWhitespace();
130	
131	        // one optional type selector
132	        if (tq.matchesWord() || tq.matches("*|"))
133	            left = byTag();
134	        else if (tq.matchChomp('*'))
135	            left = new Evaluator.AllElements();
136	
137	        // zero or more subclasses (#, ., [)
138	        while(true) {
139	            Evaluator right = parseSubclass();
140	            if (right != null) {
141	                left = and(left, right);
142	            }
143	            else break; // no more simple tokens
144	        }
145	
146	        if (left == null)
147	            throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
148	        return left;
149	    }
150	
151	    static Evaluator combinator(Evaluator left, char combinator, Evaluator right) {
152	        switch (combinator) {
153	            case '>':
154	                ImmediateParentRun run = left instanceof ImmediateParentRun ?
155	                    (ImmediateParentRun) left : new ImmediateParentRun(left);
156	                run.add(right);
157	                return run;
158	            case ' ':
159	                return and(new StructuralEvaluator.Ancestor(left), right);
160	            case '+':
161	                return and(new StructuralEvaluator.ImmediatePreviousSibling(left), right);
162	            case '~':
163	                return and(new StructuralEvaluator.PreviousSibling(left), right);
164	            default:
165	                throw new Selector.SelectorParseException("Unknown combinator '%s'", combinator);
166	        }
167	    }
168	
169	    @Nullable Evaluator parseSubclass() {
170	        //  Subclass: ID | Class | Attribute | Pseudo
171	        if      (tq.matchChomp('#'))    return byId();
172	        else if (tq.matchChomp('.'))    return byClass();
173	        else if (tq.matches('['))       return byAttribute();
174	        else if (tq.matchChomp("::"))   return parseNodeSelector(); // ::comment etc
175	        else if (tq.matchChomp(':'))    return parsePseudoSelector();
176	        else                            return null;
177	    }
178	
179	    /** Merge two evals into an Or. */
180	    static Evaluator or(Evaluator left, Evaluator right) {
181	        if (left instanceof CombiningEvaluator.Or) {
182	            ((CombiningEvaluator.Or) left).add(right);
183	            return left;
184	        }
185	        return new CombiningEvaluator.Or(left, right);
186	    }
187	
188	    /** Merge two evals into an And. */
189	    static Evaluator and(@Nullable Evaluator left, Evaluator right) {
190	        if (left == null) return right;
191	        if (left instanceof CombiningEvaluator.And) {
192	            ((CombiningEvaluator.And) left).add(right);
193	            return left;
194	        }
195	        return new CombiningEvaluator.And(left, right);
196	    }
197	
198	    private Evaluator parsePseudoSelector() {
199	        final String pseudo = tq.consumeCssIdentifier();
200	        switch (pseudo) {
201	            case "lt":
202	                return new Evaluator.IndexLessThan(consumeIndex());
203	            case "gt":
204	                return new Evaluator.IndexGreaterThan(consumeIndex());
205	            case "eq":
206	                return new Evaluator.IndexEquals(consumeIndex());
207	            case "has":
208	                return has();
209	            case "is":
210	                return is();
211	            case "contains":
212	                return contains(false);
213	            case "containsOwn":
214	                return contains(true);
215	            case "containsWholeText":
216	                return containsWholeText(false);
217	            case "containsWholeOwnText":
218	                return containsWholeText(true);
219	            case "containsData":
220	                return containsData();
221	            case "matches":
222	                return matches(false);
223	            case "matchesOwn":
224	                return matches(true);
225	            case "matchesWholeText":
226	                return matchesWholeText(false);
227	            case "matchesWholeOwnText":
228	                return matchesWholeText(true);
229	            case "not":
230	                return not();
231	            case "nth-child":
232	                return cssNthChild(false, false);
233	            case "nth-last-child":
234	                return cssNthChild(true, false);
235	            case "nth-of-type":
236	                return cssNthChild(false, true);
237	            case "nth-last-of-type":
238	                return cssNthChild(true, true);
239	            case "first-child":
240	                return new Evaluator.IsFirstChild();
241	            case "last-child":
242	                return new Evaluator.IsLastChild();
243	            case "first-of-type":
244	                return new Evaluator.IsFirstOfType();
245	            case "last-of-type":
246	                return new Evaluator.IsLastOfType();
247	            case "only-child":
248	                return new Evaluator.IsOnlyChild();
249	            case "only-of-type":
250	                return new Evaluator.IsOnlyOfType();
251	            case "empty":
252	                return new Evaluator.IsEmpty();
253	            case "blank":
254	                return new NodeEvaluator.BlankValue();
255	            case "root":
256	                return new Evaluator.IsRoot();
257	            case "matchText": {
258	                @SuppressWarnings("deprecation") // :matchText remains supported until its scheduled removal.
259	                Evaluator.MatchText matchText = new Evaluator.MatchText();
260	                return matchText;
261	            }
262	            default:
263	                throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
264	        }
265	    }
266	
267	    // ::comment etc
268	    private Evaluator parseNodeSelector() {
269	        final String pseudo = tq.consumeCssIdentifier();
270	        inNodeContext = true;  // Enter node context
271	
272	        Evaluator left;
273	        switch (pseudo) {
274	            case "node":
275	                left = new NodeEvaluator.InstanceType(Node.class, pseudo);
276	                break;
277	            case "leafnode":
278	                left = new NodeEvaluator.InstanceType(LeafNode.class, pseudo);
279	                break;
280	            case "text":
281	                left = new NodeEvaluator.InstanceType(TextNode.class, pseudo);
282	                break;
283	            case "comment":
284	                left = new NodeEvaluator.InstanceType(Comment.class, pseudo);
285	                break;
286	            case "data":
287	                left = new NodeEvaluator.InstanceType(DataNode.class, pseudo);
288	                break;
289	            case "cdata":
290	                left = new NodeEvaluator.InstanceType(CDataNode.class, pseudo);
291	                break;
292	            default:
293	                throw new Selector.SelectorParseException(
294	                    "Could not parse query '%s': unknown node type '::%s'", query, pseudo);
295	        }
296	
297	        // Handle following subclasses in node context (like ::comment:contains())
298	        Evaluator right;
299	        while ((right = parseSubclass()) != null) {
300	            left = and(left, right);
301	        }
302	
303	        inNodeContext = false;
304	        return left;
305	    }
306	
307	    private Evaluator byId() {
308	        String id = tq.consumeCssIdentifier();
309	        Validate.notEmpty(id);
310	        return new Evaluator.Id(id);
311	    }
312	
313	    private Evaluator byClass() {
314	        String className = tq.consumeCssIdentifier();
315	        Validate.notEmpty(className);
316	        return new Evaluator.Class(className.trim());
317	    }
318	
319	    private Evaluator byTag() {
320	        // todo - these aren't dealing perfectly with case sensitivity. For case sensitive parsers, we should also make
321	        // the tag in the selector case-sensitive (and also attribute names). But for now, normalize (lower-case) for
322	        // consistency - both the selector and the element tag
323	        String tagName = normalize(tq.consumeElementSelector());
324	        Validate.notEmpty(tagName);
325	
326	        // namespaces:
327	        if (tagName.startsWith("*|")) { // namespaces: wildcard match equals(tagName) or ending in ":"+tagName
328	            String plainTag = tagName.substring(2); // strip *|
329	            return new CombiningEvaluator.Or(
330	                new Evaluator.Tag(plainTag),
331	                new Evaluator.TagEndsWith(":" + plainTag)
332	            );
333	        } else if (tagName.endsWith("|*")) { // ns|*
334	            String ns = tagName.substring(0, tagName.length() - 2) + ":"; // strip |*, to ns:
335	            return new Evaluator.TagStartsWith(ns);
336	        } else if (tagName.contains("|")) { // flip "abc|def" to "abc:def"
337	            tagName = tagName.replace("|", ":");
338	        }
339	
340	        return new Evaluator.Tag(tagName);
341	    }
342	
343	    private Evaluator byAttribute() {
344	        try (TokenQueue cq = new TokenQueue(tq.chompBalanced('[', ']'))) {
345	            return evaluatorForAttribute(cq);
346	        }
347	    }
348	
349	    private Evaluator evaluatorForAttribute(TokenQueue cq) {
350	        String key = cq.consumeToAny(AttributeEvals); // eq, not, start, end, contain, match, (no val)
351	        key = normalize(key);
352	        Validate.notEmpty(key);
353	        Validate.isFalse(key.equals("abs:"), "Absolute attribute key must have a name");
354	        cq.consumeWhitespace();
355	        final Evaluator eval;
356	
357	        if (cq.isEmpty()) {
358	            if (key.startsWith("^"))
359	                eval = new Evaluator.AttributeStarting(key.substring(1));
360	            else if (key.equals("*")) // any attribute
361	                eval = new Evaluator.AttributeStarting("");
362	            else
363	                eval = new Evaluator.Attribute(key);
364	        } else {
365	            if (cq.matchChomp('='))
366	                eval = new Evaluator.AttributeWithValue(key, cq.remainder());
367	            else if (cq.matchChomp("!="))
368	                eval = new Evaluator.AttributeWithValueNot(key, cq.remainder());
369	            else if (cq.matchChomp("^="))
370	                eval = new Evaluator.AttributeWithValueStarting(key, cq.remainder());
371	            else if (cq.matchChomp("$="))
372	                eval = new Evaluator.AttributeWithValueEnding(key, cq.remainder());
373	            else if (cq.matchChomp("*="))
374	                eval = new Evaluator.AttributeWithValueContaining(key, cq.remainder());
375	            else if (cq.matchChomp("~="))
376	                eval = new Evaluator.AttributeWithValueMatching(key, Regex.compile(cq.remainder()));
377	            else
378	                throw new Selector.SelectorParseException(
379	                    "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
380	        }
381	        return eval;
382	    }
383	
384	    //pseudo selectors :first-child, :last-child, :nth-child, ...
385	    private static final Pattern NthStepOffset = Pattern.compile("(([+-])?(\\d+)?)n(\\s*([+-])?\\s*\\d+)?", Pattern.CASE_INSENSITIVE);
386	    private static final Pattern NthOffset = Pattern.compile("([+-])?(\\d+)");
387	
388	    private Evaluator cssNthChild(boolean last, boolean ofType) {
389	        String raw = consumeParens(); // arg is like "odd", or "-n+2", within nth-child(odd), optionally followed by " of S"
390	        final int ofIdx = indexOfOfClause(raw);
391	        final String arg = normalize(ofIdx >= 0 ? raw.substring(0, ofIdx) : raw);
392	        final boolean hasOf = ofIdx >= 0;
393	
394	        if (hasOf && ofType)
395	            throw new Selector.SelectorParseException(
396	                "Could not parse query '%s': 'of S' is only supported by :nth-child and :nth-last-child", query);
397	
398	        final int step, offset;
399	        if ("odd".equals(arg)) {
400	            step = 2;
401	            offset = 1;
402	        } else if ("even".equals(arg)) {
403	            step = 2;
404	            offset = 0;
405	        } else {
406	            Matcher stepOffsetM, stepM;
407	            if ((stepOffsetM = NthStepOffset.matcher(arg)).matches()) {
408	                if (stepOffsetM.group(3) != null) // has digits, like 3n+2 or -3n+2
409	                    step = Integer.parseInt(stepOffsetM.group(1).replaceFirst("^\\+", ""));
410	                else // no digits, might be like n+2, or -n+2. if group(2) == "-", it’s -1;
411	                    step = "-".equals(stepOffsetM.group(2)) ? -1 : 1;
412	                offset =
413	                    stepOffsetM.group(4) != null ? Integer.parseInt(stepOffsetM.group(4).replaceFirst("^\\+", "")) : 0;
414	            } else if ((stepM = NthOffset.matcher(arg)).matches()) {
415	                step = 0;
416	                offset = Integer.parseInt(stepM.group().replaceFirst("^\\+", ""));
417	            } else {
418	                throw new Selector.SelectorParseException("Could not parse nth-index '%s': unexpected format", arg);
419	            }
420	        }
421	
422	        if (hasOf) {
423	            String subQuery = raw.substring(ofIdx + 2).trim(); // skip the "of" keyword
424	            Validate.notEmpty(subQuery, ":nth-child(An+B of S) selector S must not be empty");
425	            Evaluator selector = parse(subQuery); // a comma-separated complex selector list; validates the full grammar
426	            return new Evaluator.IsNthChildOf(step, offset, last, selector);
427	        }
428	
429	        return ofType
430	            ? (last ? new Evaluator.IsNthLastOfType(step, offset) : new Evaluator.IsNthOfType(step, offset))
431	            : (last ? new Evaluator.IsNthLastChild(step, offset) : new Evaluator.IsNthChild(step, offset));
432	    }
433	
434	    /**
435	     Finds the index of the {@code of} keyword separating An+B from the selector list in an
436	     {@code :nth-child(An+B of S)} argument. The keyword must be bounded on both sides by whitespace, and is not
437	     matched inside quoted strings (so attribute values containing " of " are preserved).
438	     @return the index of the 'o' in 'of', or -1 if there is no of clause
439	     */
440	    private static int indexOfOfClause(String arg) {
441	        boolean inSingle = false;
442	        boolean inDouble = false;
443	        boolean prevEscaped = false;
444	        for (int i = 0; i < arg.length(); i++) {
445	            char c = arg.charAt(i);
446	            if (c == '\\' && i + 1 < arg.length()) {
447	                i++; // skip the escaped char
448	                prevEscaped = true;
449	                continue;
450	            }
451	            if (!inDouble && c == '\'')
452	                inSingle = !inSingle;
453	            else if (!inSingle && c == '"')
454	                inDouble = !inDouble;
455	
456	            if (!inSingle && !inDouble && !prevEscaped
457	                && i > 0 && StringUtil.isWhitespace(arg.charAt(i - 1))
458	                && arg.regionMatches(true, i, "of", 0, 2)
459	                && i + 2 < arg.length() && StringUtil.isWhitespace(arg.charAt(i + 2))) {
460	                return i;
461	            }
462	            prevEscaped = false;
463	        }
464	        return -1;
465	    }
466	
467	    private String consumeParens() {
468	        return tq.chompBalanced('(', ')');
469	    }
470	
471	    private int consumeIndex() {
472	        String index = consumeParens().trim();
473	        Validate.isTrue(StringUtil.isNumeric(index), "Index must be numeric");
474	        return Integer.parseInt(index);
475	    }
476	
477	    // pseudo selector :has(el)
478	    private Evaluator has() {
479	        return parseNested(StructuralEvaluator.Has::new, ":has() must have a selector");
480	    }
481	
482	    // pseudo selector :is()
483	    private Evaluator is() {
484	        return parseNested(StructuralEvaluator.Is::new, ":is() must have a selector");
485	    }
486	
487	    private Evaluator parseNested(Function<Evaluator, Evaluator> func, String err) {
488	        Validate.isTrue(tq.matchChomp('('), err);
489	        Evaluator eval = parseSelectorGroup();
490	        Validate.isTrue(tq.matchChomp(')'), err);
491	        return func.apply(eval);
492	    }
493	
494	    // pseudo selector :contains(text), containsOwn(text)
495	    private Evaluator contains(boolean own) {
496	        String query = own ? ":containsOwn" : ":contains";
497	        String searchText = TokenQueue.unescape(consumeParens());
498	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
499	
500	        if (inNodeContext)
501	            return new NodeEvaluator.ContainsValue(searchText);
502	
503	        return own
504	            ? new Evaluator.ContainsOwnText(searchText)
505	            : new Evaluator.ContainsText(searchText);
506	    }
507	
508	    private Evaluator containsWholeText(boolean own) {
509	        String query = own ? ":containsWholeOwnText" : ":containsWholeText";
510	        String searchText = TokenQueue.unescape(consumeParens());
511	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
512	        return own
513	            ? new Evaluator.ContainsWholeOwnText(searchText)
514	            : new Evaluator.ContainsWholeText(searchText);
515	    }
516	
517	    // pseudo selector :containsData(data)
518	    private Evaluator containsData() {
519	        String searchText = TokenQueue.unescape(consumeParens());
520	        Validate.notEmpty(searchText, ":containsData(text) query must not be empty");
521	        return new Evaluator.ContainsData(searchText);
522	    }
523	
524	    // :matches(regex), matchesOwn(regex)
525	    private Evaluator matches(boolean own) {
526	        String query = own ? ":matchesOwn" : ":matches";
527	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
528	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
529	        Regex pattern = Regex.compile(regex);
530	
531	        if (inNodeContext)
532	            return new NodeEvaluator.MatchesValue(pattern);
533	
534	        return own
535	            ? new Evaluator.MatchesOwn(pattern)
536	            : new Evaluator.Matches(pattern);
537	    }
538	
539	    // :matches(regex), matchesOwn(regex)
540	    private Evaluator matchesWholeText(boolean own) {
541	        String query = own ? ":matchesWholeOwnText" : ":matchesWholeText";
542	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
543	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
544	
545	        Regex pattern = Regex.compile(regex);
546	        return own
547	            ? new Evaluator.MatchesWholeOwnText(pattern)
548	            : new Evaluator.MatchesWholeText(pattern);
549	    }
550	
551	    // :not(selector)
552	    private Evaluator not() {
553	        String subQuery = consumeParens();
554	        Validate.notEmpty(subQuery, ":not(selector) subselect must not be empty");
555	
556	        return new StructuralEvaluator.Not(parse(subQuery));
557	    }
558	
559	    @Override
560	    public String toString() {
561	        return query;
562	    }
563	
564	    @Override
565	    public void close() {
566	        tq.close();
567	    }
