        try {
            Elements els = doc.select(query);
            StringBuilder sb = new StringBuilder();
            for (Element e : els) sb.append('#').append(e.id()).append(' ');
            System.out.println(query + "  ->  " + sb);
        } catch (Exception e) {
            System.out.println(query + "  ->  ERROR: " + e.getMessage());
