import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.jsoup.select.QueryParser;

public class Probe4 {
    static void q(Document doc, String query) {
        try {
            Elements els = doc.select(query);
            StringBuilder sb = new StringBuilder();
            for (Element e : els) sb.append('#').append(e.id()).append(' ');
            System.out.println(query + "  ->  " + sb);
        } catch (Exception e) {
            System.out.println(query + "  ->  ERROR: " + e.getMessage());
        }
    }
    public static void main(String[] args) {
        Document doc = Jsoup.parse("<article id=a><h1></h1><h2></h2><p><b></b><i></i></p></article><article id=z><h1></h1><p></p><b></b><i></i></article>");
        // nested :has anchors to inner element, not outer A
        q(doc, "article:has(p:has(:scope > b + i))");   // #a
        // :is combination container re-anchors
        q(doc, "article:has(p:is(:has(> b + i)))");     // #a
        // :not exclusion container re-anchors
        q(doc, "article:has(p:not(:has(> b + i)))");    // #z (its p has no b+i children)
        // :is with leading combinator inside :has
        q(doc, "article:has(:is(> h1 + h2))");          // #a
        // toString sanity
        System.out.println(QueryParser.parse("article:has(:scope > p > b + i)"));
        System.out.println(QueryParser.parse("article:has(+ article)"));
        // element-started > X still works
        Element a = doc.expectFirst("#a");
        System.out.println("a.select(\"> h2\") size: " + a.select("> h2").size());
    }
}
